# -*- coding: utf-8 -*-
from content import PAGES,SEG
def more(slug,*secs): PAGES[slug]['sections']+=list(secs)

more('reparacion-de-caminadoras-cali',
 ('Tipos de caminadora y por qué importa para la reparación','<p>Las caminadoras <b>eléctricas</b> mueven la banda con un motor y casi siempre tienen consola y, en muchos modelos, motor de inclinación. Las <b>mecánicas o magnéticas</b> no tienen motor: la banda se mueve con tu paso. Cada tipo falla de forma distinta, por eso la marca y el modelo son los datos más importantes al pedir una revisión.</p><p>En las eléctricas también influye la potencia del motor y si es de uso doméstico o comercial. Un motor doméstico que trabaja muchas horas al día se calienta y se desgasta antes, algo común cuando una caminadora de casa se usa en un gimnasio pequeño o por varias personas.</p>'),
 ('Cuidados entre una revisión y otra','<ul><li>Limpia el polvo alrededor del motor y debajo de la banda con el equipo desconectado.</li><li>No la uses con calzado que traiga arena o barro: se mete bajo la banda y desgasta rodillos y tabla.</li><li>Ponla sobre una superficie nivelada y lejos de la humedad y el sol directo.</li><li>Conéctala directo a la pared, sin extensiones.</li><li>Revisa la tornillería de la estructura y la consola una vez al mes.</li><li>Sigue las indicaciones de lubricación de tu manual.</li></ul>'),
 ('Señales de desgaste que conviene atender pronto','<ul><li>Bordes de la banda deshilachados o brillantes.</li><li>Olor a plástico caliente al usarla.</li><li>Vibración o ruido que antes no tenía.</li><li>Velocidad irregular o consola que muestra errores de forma intermitente.</li><li>La banda se corre cada vez más seguido.</li></ul><p>Atender estas señales a tiempo suele ser más económico que esperar a que falle el motor o la tarjeta.</p>'))
more('reparacion-bicicletas-spinning-cali',
 ('Tipos de resistencia y de transmisión','<p>Hay bicicletas con <b>freno de fricción</b> (una pastilla de fieltro o caucho que roza el volante de inercia) y con <b>resistencia magnética</b> (imanes, sin contacto). La de fricción se desgasta y se ajusta; la magnética casi no se desgasta, pero depende de la perilla, el cable o el motor de resistencia.</p><p>La transmisión puede ser por <b>cadena</b>, que necesita lubricación, o por <b>correa</b>, que es más silenciosa y suele pedir menos mantenimiento. Conocer cuál tiene tu bicicleta ayuda a encontrar la falla más rápido.</p>'),
 ('Mantenimiento básico entre revisiones','<ul><li>Limpia el sudor del marco y del manillar después de entrenar: es corrosivo.</li><li>Aprieta los pedales, el sillín y el manillar cada cierto tiempo.</li><li>Si la transmisión es por cadena, mantenla limpia y lubricada.</li><li>Guarda la bicicleta en un lugar seco.</li></ul>'),
 ('Señales de que necesita una revisión','<ul><li>Ruido nuevo al pedalear o al ponerte de pie.</li><li>Juego en las manivelas o en los pedales.</li><li>La resistencia se siente irregular o no sube.</li><li>El volante tiene un movimiento brusco o desigual.</li></ul>'))
more('reparacion-maquinas-multifuncionales-cali',
 ('Revisión de seguridad antes de entrenar','<ul><li>Cables sin hilos sueltos, torceduras ni zonas aplastadas.</li><li>Poleas que giran libres, sin roce ni ruido.</li><li>Pin selector de la pila de pesas firme y sin juego.</li><li>Agarres y manijas sin desgaste ni rajaduras.</li><li>Estructura estable, sin tornillos flojos.</li><li>Tapicería sin rotos ni hundimientos.</li></ul>'),
 ('Mantenimiento básico','<ul><li>Limpia las barras guía con un paño seco y aplica el lubricante recomendado por el fabricante, en poca cantidad.</li><li>Revisa la tornillería con regularidad, sobre todo en zonas de mucho uso.</li><li>No sobrecargues la máquina ni uses un peso mayor al indicado.</li><li>Limpia la tapicería y evita la humedad acumulada.</li></ul>'))
more('reparacion-eliptica-cali',
 ('Tipos de elíptica','<p>Las elípticas se diferencian por la posición del volante de inercia: <b>delantero</b>, <b>trasero</b> o <b>central</b>. También cambia el tipo de resistencia, que puede ser magnética o por fricción. Cada diseño tiene piezas distintas, así que conviene indicar la marca y el modelo al pedir la revisión.</p>'),
 ('Mantenimiento básico','<ul><li>Aprieta periódicamente pedales, brazos y tornillería.</li><li>Limpia el sudor después de usarla.</li><li>Si el ruido aparece o crece, no esperes: un buje desgastado puede dañar otras piezas.</li><li>Revisa que el equipo esté nivelado sobre el piso.</li></ul>'))
more('mantenimiento-equipos-gimnasio-cali',
 ('Checklist de rutina para el personal del gimnasio','<ul><li><b>A diario:</b> limpiar cada equipo, revisar a simple vista cables, pedales, bandas y llaves de seguridad, y retirar de servicio cualquier máquina con ruido o falla.</li><li><b>Cada semana:</b> revisar tornillería, nivelación y estado de tapicerías.</li><li><b>Cada mes:</b> revisar la lubricación según el manual y el estado de bandas, cables y poleas.</li></ul><p>Este chequeo no reemplaza la revisión del técnico, pero detecta problemas a tiempo y evita accidentes.</p>'),
 ('Qué pasa si no se hace mantenimiento','<ul><li>Más paradas de equipos, justo en las horas de mayor uso.</li><li>Reparaciones más costosas por piezas que se dañan en cadena.</li><li>Mayor riesgo de lesiones por cables, pedales o estructuras con desgaste.</li><li>Clientes que notan equipos en mal estado.</li></ul>'))
more('reparacion-equipos-gimnasio-a-domicilio-cali',
 ('Ventajas del servicio a domicilio','<ul><li>No tienes que desarmar, empacar ni transportar un equipo pesado.</li><li>El técnico ve el equipo en su lugar de uso, con la instalación eléctrica y el piso reales.</li><li>Puedes ver la falla y preguntar en el momento.</li><li>Ahorras tiempo: coordinamos la visita por WhatsApp.</li></ul>'),
 ('Si el equipo debe llevarse al taller','<p>Algunas reparaciones requieren piezas o herramientas que no se pueden resolver en el sitio. Si es el caso, te lo explicamos antes de mover el equipo y coordinamos cómo hacerlo.</p>'))
# guías
more('caminadora-no-enciende',('Cómo evitar que vuelva a pasar','<ul><li>Conéctala a una toma en buen estado y sin extensiones.</li><li>Si tu zona tiene apagones o subidas de tensión, usa un protector o regulador adecuado a la potencia del equipo.</li><li>Desconéctala cuando no la uses por varios días.</li><li>No tires del cable para desconectarla.</li></ul>'))
more('banda-de-caminadora-patina-o-se-corre',('Cómo prevenirlo','<ul><li>Usa la caminadora centrado sobre la banda y no te apoyes de forma constante en un solo lado.</li><li>Revisa la alineación cada cierto tiempo, sobre todo si la mueves de lugar.</li><li>Mantén la lubricación al día si tu modelo la requiere.</li></ul>'))
more('ruido-en-la-caminadora',('Cuándo el ruido es una urgencia','<p>Deja de usar la caminadora si el ruido es un golpe fuerte, si huele a quemado, si ves humo o chispas o si la banda roza el marco. En esos casos seguir usándola puede dañar el motor o la tarjeta y poner en riesgo a quien la usa.</p>'))
more('caminadora-se-apaga-sola',('Qué datos ayudan al diagnóstico','<ul><li>¿Se apaga a los pocos minutos o después de mucho rato?</li><li>¿Pasa con cualquier persona o solo con más peso?</li><li>¿Se apaga a cierta velocidad o inclinación?</li><li>¿Muestra algún código en la consola?</li></ul><p>Con esa información acotamos la causa antes de la visita.</p>'))
more('bicicleta-spinning-hace-ruido',('Mantenimiento que evita ruidos','<ul><li>Limpia el sudor después de cada uso.</li><li>Revisa la tornillería cada mes.</li><li>Lubrica la cadena si tu bicicleta la tiene.</li></ul>'))
more('cuanto-cuesta-reparar-una-caminadora',('Para pedir un costo más exacto, cuéntanos','<ul><li>Marca y modelo del equipo.</li><li>Si es de uso doméstico o de gimnasio.</li><li>Cuándo empezó la falla y qué pasó justo antes.</li><li>Tu barrio en Cali.</li></ul>'))
more('cada-cuanto-lubricar-una-caminadora',('Qué hace un mantenimiento completo','<p>Además de lubricar, un mantenimiento revisa la tensión y alineación de la banda, el estado de rodillos y correa, la limpieza interna del motor y la tornillería. Se hace con el equipo desconectado y con las herramientas adecuadas.</p>'))
